using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Net.Http;using System.Reflection;using System.Runtime.InteropServices;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;
public sealed class ThinArtifact {public string kind,file,url,sha256,destination,package,version;public long bytes,unpackedBytes;public VoiceArchive Archive(string resolved){return new VoiceArchive{file=file,url=resolved,bytes=bytes,sha256=sha256,unpackedBytes=unpackedBytes};}}
public sealed class ThinConfig {public string version;public bool selfDownloading;public long installedBytes;public ThinArtifact[] artifacts;}
public static class ThinInstall {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string target,string source,IntPtr reserved);
 public static bool Publisher(string host){host=host.ToLowerInvariant();return new[]{"storage.yandexcloud.net","nodejs.org","api.nuget.org","globalcdn.nuget.org","files.pythonhosted.org","download.pytorch.org","download-r2.pytorch.org","huggingface.co"}.Contains(host)||host.EndsWith(".hf.co",StringComparison.Ordinal)||host.EndsWith(".huggingface.co",StringComparison.Ordinal);}
 public static ThinConfig Load(){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("setup-config.json"))using(var reader=new StreamReader(stream,Encoding.UTF8)){var c=new JavaScriptSerializer().Deserialize<ThinConfig>(reader.ReadToEnd());if(!c.selfDownloading||!Regex.IsMatch(c.version??"","^[a-z0-9.-]{8,80}$")||c.artifacts==null||c.artifacts.Length<12||c.artifacts.Length>180||c.installedBytes<1)throw new IOException("Некорректный установщик.");foreach(var a in c.artifacts){var u=new Uri(a.url);if(u.Scheme!="https"||!Publisher(u.DnsSafeHost)||!String.IsNullOrEmpty(u.UserInfo)||!Regex.IsMatch(a.sha256??"","^[a-f0-9]{64}$")||a.bytes<=0||a.file!=Path.GetFileName(a.file)||a.file.IndexOf(':')>=0||!new[]{"python","node","app","wheel","model"}.Contains(a.kind))throw new IOException("Некорректный источник компонента.");if(a.kind=="model"&&(!a.destination.StartsWith("model/",StringComparison.Ordinal)||a.destination.Split('/').Any(p=>p==".."||p=="")))throw new IOException("Некорректный путь модели.");}if(c.artifacts.Count(a=>a.kind=="app")!=1||c.artifacts.Count(a=>a.kind=="python")!=1||c.artifacts.Count(a=>a.kind=="node")!=1||c.artifacts.Count(a=>a.kind=="model")!=11)throw new IOException("Неполный комплект компонентов.");return c;}}
 public static async Task<string> Resolve(string source,CancellationToken ct){Uri current=new Uri(source);using(var client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false,UseDefaultCredentials=false})){client.Timeout=TimeSpan.FromSeconds(40);for(int n=0;n<8;n++){ct.ThrowIfCancellationRequested();if(current.Scheme!="https"||!Publisher(current.DnsSafeHost))throw new IOException("Недопустимое перенаправление загрузки.");using(var request=new HttpRequestMessage(HttpMethod.Head,current))using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct)){int status=(int)response.StatusCode;if(status>=300&&status<=399&&response.Headers.Location!=null){current=new Uri(current,response.Headers.Location);continue;}if(!response.IsSuccessStatusCode)throw new IOException("Источник временно недоступен. Повторите установку позже.");return current.AbsoluteUri;}}}throw new IOException("Слишком много перенаправлений.");}
 public static void LinkOrCopy(string source,string target){Directory.CreateDirectory(Path.GetDirectoryName(target));if(File.Exists(target))throw new IOException("Файл установки уже существует.");if(!CreateHardLink(target,source,IntPtr.Zero))File.Copy(source,target,false);}
 public static string CachedModel(ThinArtifact a){if(a.kind!="model")return null;string hub=Environment.GetEnvironmentVariable("HUGGINGFACE_HUB_CACHE");if(String.IsNullOrEmpty(hub)){string hf=Environment.GetEnvironmentVariable("HF_HOME");hub=String.IsNullOrEmpty(hf)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".cache","huggingface","hub"):Path.Combine(hf,"hub");}string candidate=Path.Combine(hub,"models--siriusfreak--qwen3-tts-12hz-1.7b-ru-stress-cf","snapshots","c16b3af3db3095120efc1ebb73f6522442bcb3b1",a.destination.Substring(6).Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(candidate)||new FileInfo(candidate).Length!=a.bytes)return null;return VoiceInstallCore.HashFile(candidate)==a.sha256?candidate:null;}
 public static void Packages(string staging,IEnumerable<ThinArtifact> artifacts,string cache,CancellationToken ct){
  string wheelhouse=Path.Combine(staging,"wheelhouse");Directory.CreateDirectory(wheelhouse);var requirement=new StringBuilder();foreach(var a in artifacts.Where(a=>a.kind=="wheel")){LinkOrCopy(Path.Combine(cache,a.sha256+".blob"),Path.Combine(wheelhouse,a.file));requirement.AppendLine(a.package+"=="+a.version+" --hash=sha256:"+a.sha256);}
  string lockFile=Path.Combine(staging,"requirements.lock");File.WriteAllText(lockFile,requirement.ToString(),new UTF8Encoding(false));string python=Path.Combine(staging,"runtime","python.exe"),site=Path.Combine(staging,"runtime","Lib","site-packages");
  var info=new ProcessStartInfo(python,"-I -B -X utf8 -m pip --isolated install --no-index --no-deps --upgrade --no-compile --no-cache-dir --disable-pip-version-check --no-warn-script-location --only-binary=:all: --require-hashes --find-links \""+wheelhouse+"\" --target \""+site+"\" -r \""+lockFile+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=staging,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};info.EnvironmentVariables["PIP_CONFIG_FILE"]="NUL";
  using(var process=Process.Start(info)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();using(ct.Register(()=>{try{process.Kill();}catch{}})){process.WaitForExit();ct.ThrowIfCancellationRequested();File.WriteAllText(Path.Combine(staging,"sdk-install.log"),output.GetAwaiter().GetResult()+error.GetAwaiter().GetResult(),Encoding.UTF8);if(process.ExitCode!=0)throw new IOException("Не удалось подготовить библиотеки. Журнал сохранён в папке установки; загрузки сохраняются для повтора.");}}
  Directory.Delete(wheelhouse,true);File.Delete(lockFile);
 }
 public static void Prepare(ThinConfig config,string staging,string cache,Action<string> report,CancellationToken ct){
  ThinArtifact python=config.artifacts.Single(a=>a.kind=="python"),app=config.artifacts.Single(a=>a.kind=="app"),node=config.artifacts.Single(a=>a.kind=="node");string unpack=Path.Combine(staging,"python-package");report("Подготавливаю Python…");VoiceInstallCore.Extract(Path.Combine(cache,python.sha256+".blob"),unpack,python.unpackedBytes,n=>{},false,ct);Directory.Move(Path.Combine(unpack,"tools"),Path.Combine(staging,"runtime"));Directory.Delete(unpack,true);
  LinkOrCopy(Path.Combine(cache,node.sha256+".blob"),Path.Combine(staging,"runtime","node.exe"));VoiceInstallCore.Extract(Path.Combine(cache,app.sha256+".blob"),staging,app.unpackedBytes,n=>{},true,ct);
  foreach(var a in config.artifacts.Where(a=>a.kind=="model")){ct.ThrowIfCancellationRequested();string target=Path.GetFullPath(Path.Combine(staging,a.destination.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(Path.GetFullPath(staging)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Путь модели вне установки.");LinkOrCopy(Path.Combine(cache,a.sha256+".blob"),target);}
  report("Устанавливаю проверенные версии библиотек…");Packages(staging,config.artifacts,cache,ct);ct.ThrowIfCancellationRequested();
 }
}
public sealed class ThinSetupForm:Form {
 readonly ThinConfig config;readonly Label status=new Label();readonly ProgressBar progress=new ProgressBar();readonly Button install=new Button(),cancel=new Button();CancellationTokenSource cancellation;bool busy=false,committed=false;
 public ThinSetupForm(ThinConfig c){config=c;Text="Установка голоса «Уют-7» · Qwen TTS";Width=690;Height=450;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(12,25,41);ForeColor=Color.White;var title=new Label{Left=24,Top=22,Width=620,Height=38,Text="Голос «Уют-7» · установка в один шаг",Font=new Font("Segoe UI",16,FontStyle.Bold)};Controls.Add(title);var description=new Label{Left=24,Top=75,Width=620,Height=125,Text="Установщик скачает модель и библиотеки из официальных источников.\r\nУ Nexus хранится только небольшой модуль подключения.\r\n\r\nПолная загрузка: "+(c.artifacts.Sum(a=>a.bytes)/1073741824d).ToString("0.0")+" ГБ; уже имеющаяся модель будет использована повторно.\r\nПосле установки — около 10 ГБ. Windows x64 · NVIDIA с 8 ГБ.\r\nОблачный API-ключ не нужен. Установка без прав администратора."};Controls.Add(description);progress.SetBounds(24,215,620,22);Controls.Add(progress);status.SetBounds(24,252,620,80);status.Text="Проверим видеокарту и место до начала загрузки.";Controls.Add(status);install.SetBounds(24,350,240,40);install.Text="Установить голос";install.ForeColor=Color.Black;install.Click+=async(s,e)=>await Run();Controls.Add(install);cancel.SetBounds(424,350,220,40);cancel.Text="Закрыть";cancel.ForeColor=Color.Black;cancel.Click+=(s,e)=>{if(busy&&!committed)cancellation.Cancel();else Close();};Controls.Add(cancel);FormClosing+=(s,e)=>{if(busy&&!committed){e.Cancel=true;cancellation.Cancel();}};}
 void Report(string text,int value){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action(()=>Report(text,value)));return;}status.Text=text;progress.Value=Math.Max(0,Math.Min(100,value));}
 async Task Run(){if(busy)return;busy=true;committed=false;install.Enabled=false;cancel.Text="Остановить";cancellation=new CancellationTokenSource();string staging=null;
  try{if(!Environment.Is64BitOperatingSystem)throw new IOException("Нужен Windows x64.");var gpu=await Task.Run(()=>VoiceInstallCore.GpuDevice());string home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Akronikl","LocalVoice"),versions=Path.Combine(home,"versions"),target=Path.Combine(versions,config.version),cache=Path.Combine(home,"downloads");Directory.CreateDirectory(versions);Directory.CreateDirectory(cache);
   if(Directory.Exists(target)){if(!File.Exists(Path.Combine(target,"INSTALL_COMPLETE.json")))throw new IOException("Предыдущая установка не завершена. Удалите её через параметры Windows и запустите установщик снова.");File.WriteAllText(Path.Combine(target,"cuda-device.json"),new JavaScriptSerializer().Serialize(new{uuid=gpu.uuid}),Encoding.UTF8);VoiceInstallCore.Register(target,config.version);VoiceInstallCore.Shortcut(target);VoiceInstallCore.Launch(target);Report("Запускаю установленный голос. Возьмите код в окне модуля.",100);return;}
   Report("Проверяю уже имеющуюся модель…",0);var reused=await Task.Run(()=>config.artifacts.Where(a=>a.kind=="model").Select(a=>new{artifact=a,source=ThinInstall.CachedModel(a)}).Where(x=>x.source!=null).ToDictionary(x=>x.artifact.sha256,x=>x.source));long saved=reused.Where(x=>String.Equals(Path.GetPathRoot(x.Value),Path.GetPathRoot(home),StringComparison.OrdinalIgnoreCase)).Sum(x=>config.artifacts.First(a=>a.sha256==x.Key).bytes),downloads=config.artifacts.Where(a=>!File.Exists(Path.Combine(cache,a.sha256+".blob"))&&!reused.ContainsKey(a.sha256)).Sum(a=>a.bytes),needed=config.installedBytes-saved+downloads+2L*1024*1024*1024;
   if(new DriveInfo(Path.GetPathRoot(home)).AvailableFreeSpace<needed)throw new IOException("Для загрузки и установки нужно не менее "+(needed/1073741824d).ToString("0.0")+" ГБ свободного места.");long completed=0,total=config.artifacts.Sum(a=>a.bytes);
   foreach(var a in config.artifacts){cancellation.Token.ThrowIfCancellationRequested();string file=Path.Combine(cache,a.sha256+".blob");if(reused.ContainsKey(a.sha256)&&!File.Exists(file))ThinInstall.LinkOrCopy(reused[a.sha256],file);long previous=completed;Report("Подготавливаю "+a.file,Math.Min(70,(int)(70*completed/total)));string resolved=File.Exists(file)?a.url:await ThinInstall.Resolve(a.url,cancellation.Token);await VoiceInstallCore.Download(a.Archive(resolved),file,n=>Report("Получено "+((previous+n)/1073741824d).ToString("0.00")+" / "+(total/1073741824d).ToString("0.00")+" ГБ",(int)(70*(previous+n)/total)),cancellation.Token);completed+=a.bytes;}
   staging=Path.Combine(versions,".installing-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);await Task.Run(()=>ThinInstall.Prepare(config,staging,cache,text=>Report(text,82),cancellation.Token));cancellation.Token.ThrowIfCancellationRequested();File.WriteAllText(Path.Combine(staging,"cuda-device.json"),new JavaScriptSerializer().Serialize(new{uuid=gpu.uuid}),Encoding.UTF8);File.WriteAllText(Path.Combine(staging,"INSTALL_COMPLETE.json"),new JavaScriptSerializer().Serialize(new{version=config.version,installedAt=DateTime.UtcNow.ToString("o"),selfDownloading=true}),Encoding.UTF8);Directory.Move(staging,target);staging=null;committed=true;cancel.Text="Закрыть";VoiceInstallCore.Register(target,config.version);VoiceInstallCore.Shortcut(target);foreach(var a in config.artifacts)File.Delete(Path.Combine(cache,a.sha256+".blob"));VoiceInstallCore.Launch(target);
   Report("Модель установлена. Подготавливаю голос; окно уже можно закрыть…",96);bool ready=false;using(var client=new HttpClient()){client.Timeout=TimeSpan.FromSeconds(2);for(int n=0;n<90;n++){try{var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(await client.GetStringAsync("http://127.0.0.1:18791/status"));if(d.ContainsKey("build")&&(string)d["build"]==config.version&&d.ContainsKey("ready")&&(bool)d["ready"]){ready=true;break;}}catch{}await Task.Delay(2000);}}Report(ready?"Голос готов. Возьмите код в окне модуля и подключите его в настройках Nexus.":"Установка завершена. Дождитесь «Голос готов» в окне модуля. Ярлык добавлен в меню «Пуск».",100);
  }catch(OperationCanceledException){Report("Остановлено. Загрузки сохранены; следующий запуск продолжит их.",0);}catch(Exception e){Report(e.Message,0);}finally{busy=false;if(!IsDisposed){install.Enabled=true;cancel.Text="Закрыть";}cancellation.Dispose();if(staging!=null)try{VoiceInstallCore.RemoveStaging(staging);}catch{}}
 }
}
public static class ThinProgram {[STAThread]public static void Main(string[] args){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Application.Run(new ThinSetupForm(ThinInstall.Load()));}catch(Exception e){MessageBox.Show(e.Message,"Установка голоса Nexus",MessageBoxButtons.OK,MessageBoxIcon.Error);}}}
